def bmi(weight_kg, height_m):
    weight = weight_kg * 1000  # в килограммах
    height = height_m * 100  # в сантиметрах
    bmi_value = weight / (height ** 2)
    bmi_category = {
        'Норма': (18.5, 24.9),
        'Надлишкова вага': (25, 29.9),
        'Ожиріння': (30, float('inf'))
    }
    for category, (lower, upper) in bmi_category.items():
        if lower <= bmi_value < upper:
            return f'{bmi_value:.2f} - {category}'
    return f'{bmi_value:.2f} - Наборка'
